  generated_linkedin: clean(row.generated_linkedin), generated_facebook: clean(row.generated_facebook), generated_instagram: clean(row.generated_instagram),
  image_url: clean(row.image_url), image_brief: clean(row.image_brief), video_url: clean(row.video_url),
  video_brief: clean(row.video_brief), video_script: clean(row.video_script),
  marketing_status: 'Pending', marketing_comment: '', marketing_reviewed_by: '', marketing_reviewed_at: '',
  owner_status: 'Waiting for Marketing', owner_comment: '', owner_reviewed_by: '', owner_reviewed_at: '',
  final_status: 'Pending Marketing Review', revision_request: '', revision_count: version - 1,
  submitted_at: now, finalized_at: '', created_at: now, updated_at: now, last_error: '', audit_version: version
} };

const clean = value => String(value ?? '').trim();
const key = value => clean(value).toLowerCase();
const now = new Date().toISOString();
const terminal = new Set(['Approved for Publishing','Changes Requested','Rejected','Published','Superseded']);
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!clean(row.audit_id) || terminal.has(clean(row.final_status)) && clean(row.finalized_at)) continue;
  const marketing = key(row.marketing_status) || 'pending';
  const owner = key(row.owner_status) || 'waiting for marketing';
  let ownerStatus = clean(row.owner_status) || 'Waiting for Marketing';
  let finalStatus = 'Pending Marketing Review';
  let revision = '';
  let finalizedAt = clean(row.finalized_at);
  let lastError = '';
  let queueAction = '';
  let marketingAt = clean(row.marketing_reviewed_at);
  let ownerAt = clean(row.owner_reviewed_at);

  const marketingNamed = Boolean(clean(row.marketing_reviewed_by));
  const ownerNamed = Boolean(clean(row.owner_reviewed_by));
  const marketingComment = clean(row.marketing_comment);
  const ownerComment = clean(row.owner_comment);

  if (marketing !== 'pending' && !marketingNamed) {
    lastError = 'marketing_reviewed_by is required before recording the marketing decision.';
  } else if (['changes requested','rejected'].includes(marketing) && !marketingComment) {
    lastError = 'Marketing comment is required for Changes Requested or Rejected.';
  } else if (marketing === 'changes requested') {
    finalStatus = 'Changes Requested'; revision = marketingComment; finalizedAt = now; queueAction = 'revise'; marketingAt = marketingAt || now;
  } else if (marketing === 'rejected') {
    finalStatus = 'Rejected'; revision = marketingComment; finalizedAt = now; queueAction = 'reject'; marketingAt = marketingAt || now;
  } else if (marketing === 'approved') {
    marketingAt = marketingAt || now;
    ownerStatus = owner === 'waiting for marketing' ? 'Pending' : clean(row.owner_status);
    finalStatus = 'Pending Owner Review';
    if (owner !== 'waiting for marketing' && owner !== 'pending' && !ownerNamed) {
      lastError = 'owner_reviewed_by is required before recording the owner decision.';
    } else if (['changes requested','rejected'].includes(owner) && !ownerComment) {
      lastError = 'Owner comment is required for Changes Requested or Rejected.';
    } else if (owner === 'changes requested') {
      finalStatus = 'Changes Requested'; revision = ownerComment; finalizedAt = now; queueAction = 'revise'; ownerAt = ownerAt || now;
    } else if (owner === 'rejected') {
      finalStatus = 'Rejected'; revision = ownerComment; finalizedAt = now; queueAction = 'reject'; ownerAt = ownerAt || now;
    } else if (owner === 'approved') {
      finalStatus = 'Approved for Publishing'; finalizedAt = now; queueAction = 'approve'; ownerAt = ownerAt || now;
    }
  }

  const changed = finalStatus !== clean(row.final_status) || ownerStatus !== clean(row.owner_status) ||
    marketingAt !== clean(row.marketing_reviewed_at) || ownerAt !== clean(row.owner_reviewed_at) ||
    lastError !== clean(row.last_error) || revision !== clean(row.revision_request) || finalizedAt !== clean(row.finalized_at);
  if (!changed && !queueAction) continue;
  out.push({ json: {
    ...row, owner_status: ownerStatus, final_status: finalStatus, revision_request: revision,
    marketing_reviewed_at: marketingAt, owner_reviewed_at: ownerAt, finalized_at: finalizedAt,
    updated_at: now, last_error: lastError, _queue_action: queueAction
  } });
}
return out;

// v9.5.6 FIX: switched from 'Run Once for Each Item' to 'Run Once for All Items'.
// In per-item mode the code must return a single object with a 'json' key, so the old
// `if (!action) return [];` crashed with "A 'json' property isn't an object" instead of
// skipping the row. In all-items mode returning fewer items is legal, so rows with no
// pending audit action are simply not emitted.
const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const action = String(row._queue_action || '');
  if (!action) continue;
  const approved = action === 'approve';
  const now = new Date().toISOString();
  const reviewers = [String(row.marketing_reviewed_by || '').trim(), String(row.owner_reviewed_by || '').trim()].filter(Boolean).join(' + ');
  out.push({ json: {
    id: row.content_id,
    status: approved ? 'Approved' : 'Needs Review',
    audit_id: row.audit_id,
    audit_status: row.final_status,
    audit_submitted_at: row.submitted_at || '',
    audit_version: approved ? Number(row.audit_version || 1) : Number(row.audit_version || 1) + 1,
    approved_by: approved ? reviewers : '',
    approved_at: approved ? now : '',
    last_error: approved ? '' : (row.revision_request || row.last_error || 'Audit changes requested.'),
    next_retry_at: '',
    updated_at: now
  } });
}
return out;

// v9.5.6 FIX: same class of bug as 'Prepare Queue Audit Decision' - `return []` is invalid in
// per-item mode. Now runs over all items so non-published rows are skipped instead of crashing.
const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  if (String(row.status || '') !== 'Published' || !String(row.audit_id || '').trim()) continue;
  out.push({ json: {
    audit_id: row.audit_id,
    final_status: 'Published',
    updated_at: new Date().toISOString(),
    last_error: ''
  } });
}
return out;

const cfg = $('Runtime Configuration').first().json;
const enabled = cfg.telegram_preview_enabled === true || String(cfg.telegram_preview_enabled).toLowerCase() === 'true';
const chatId = String(cfg.telegram_chat_id || '').trim();
if (!enabled || !chatId || chatId === 'YOUR_TELEGRAM_CHAT_ID') return [];

const inputs = $input.all();
const lockedPosts = $('Prepare Image Lock').all();
const brands = $('Read Brand Configuration').all().map(item => item.json);
const clean = value => String(value ?? '').trim();

function buildContactBlock(source) {
  const contacts = [
  ['🟢 واتساب', clean(source.whatsapp_url)],
  ['📞 هاتف', clean(source.contact_phone)],
  ['🌐 الموقع', clean(source.website_url)],
  ['📘 فيسبوك', clean(source.facebook_url)],
  ['📸 إنستغرام', clean(source.instagram_url)],
  ['✈️ تلغرام', clean(source.telegram_url)],
  ['💬 ماسنجر', clean(source.messenger_url)],
  ['✉️ إيميل', clean(source.contact_email)],
].filter(([, value]) => value);

  if (!contacts.length) return clean(source.default_cta);
  return [
    '📲 للتواصل وطلب دراسة مجانية لفاتورتك',
    ...contacts.map(([label, value]) => label + ': ' + value),
  ].join('\n');
}

function ensureContactBlock(value, contactBlock) {
  const body = clean(value);
  if (!contactBlock || body.includes('📲 للتواصل وطلب دراسة مجانية لفاتورتك')) return body;
  return body ? body + '\n\n' + contactBlock : contactBlock;
}

return inputs.flatMap((sourceItem, sourceIndex) => {
  const pairedIndex = Number.isInteger(sourceItem.pairedItem?.item)
    ? sourceItem.pairedItem.item
    : sourceIndex;
  const originalPost = lockedPosts[pairedIndex]?.json || lockedPosts[sourceIndex]?.json || {};
  const source = { ...originalPost, ...sourceItem.json };
  const brand = brands.find(item => clean(item.brand_id) === clean(source.brand_id)) || {};
  const fullSource = { ...brand, ...source };
  const company = clean(fullSource.company_name) || clean(fullSource.brand_id) || 'Peak PV';
  const topic = clean(fullSource.content_pillar) || clean(fullSource.campaign) || 'Social media content';
  const targetPlatform = clean(fullSource.target_platform).toUpperCase();
  const contentId = clean(fullSource.id);
  const intent = [fullSource.campaign, fullSource.content_pillar, fullSource.topic_idea].map(clean).join(' ').toLowerCase();
  const isOccasion = /social occasion|holiday|eid|ramadan|christmas|easter|new year|thanksgiving|labor day|independence day|good friday|palm sunday|mawlid|women.?s day|mother.?s day|army day|teacher.?s day|مناسبة|عيد|رمضان|الاستقلال|المولد|رأس السنة|الإسراء|يوم الجيش|يوم العمال|تهنئة|جمعة مباركة/.test(intent);
  const isRecruitment = /recruitment|hiring|career|job vacancy|job posting|توظيف|وظيفة|شاغر/.test(intent);
  const contactBlock = (isOccasion || isRecruitment) ? '' : buildContactBlock(fullSource);
  const entries = [
    ['FACEBOOK', fullSource.generated_facebook],
    ['INSTAGRAM', fullSource.generated_instagram],
    ['LINKEDIN', fullSource.generated_linkedin],
  ].filter(([platform, value]) => clean(value) && (!targetPlatform || platform === targetPlatform));

  return entries.map(([platform, value]) => ({
    json: {
      ...fullSource,
      telegram_chat_id: chatId,
      telegram_platform: platform,
      telegram_copy: ensureContactBlock(value, contactBlock),
      telegram_caption: ('🖼️ ' + platform + ' — ' + company + '\n🧾 ' + contentId + '\n\n' + ensureContactBlock(value, contactBlock)).slice(0, 1024),
    },
    binary: sourceItem.binary,
    pairedItem: { item: sourceIndex },
  }));
});

const photoResponse = $json;
const preview = $('Prepare Telegram Preview').item.json;
const clean = value => String(value ?? '').trim();

// v9.5.6 FIX: this node runs in 'Run Once for Each Item' mode, where the code MUST return a
// single object with a 'json' property. The old `return []` therefore crashed with
// "A 'json' property isn't an object" every time the copy already fitted in the image caption
// - which is the common case, not an edge case.
// It was also wrong in a second way: this node sits INSIDE 'Loop Telegram Platform Previews',
// and the loop is fed back by 'Telegram - Send Platform Copy'. Emitting zero items would have
// stopped that feedback and silently ended the loop, so the remaining platform previews would
// never be sent. So instead of dropping the item we always emit one and let the new IF node
// 'Separate Copy Needed?' decide whether to actually send it - both of its branches return to
// the loop, so every platform is processed.
const __fullCopy = clean(preview.telegram_copy);
const company = clean(preview.company_name) || clean(preview.brand_id) || 'Peak PV';
const platform = clean(preview.telegram_platform) || 'SOCIAL';
const contentId = clean(preview.id);
const messageId = photoResponse.result?.message_id || photoResponse.message_id || '';

if (__fullCopy.length <= 900) {
  return { json: {
    telegram_copy_needed: false,
    telegram_chat_id: preview.telegram_chat_id,
    telegram_message: '',
    telegram_platform: platform,
    content_id: contentId,
    reply_to_message_id: messageId,
  } };
}

function fitBody(value, maxLength) {
  const full = clean(value);
  if (full.length <= maxLength) return full;

  let markerIndex = full.lastIndexOf('\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udcf2 CONTACT & REQUEST SERVICE');
  if (markerIndex < 0) markerIndex = full.lastIndexOf('\ud83d\udcf2 CONTACT & REQUEST SERVICE');

  if (markerIndex >= 0) {
    const contactBlock = full.slice(markerIndex).trim();
    const availableMain = Math.max(0, maxLength - contactBlock.length - 7);
    const main = full.slice(0, markerIndex).trim().slice(0, availableMain).trim();
    return main + '\n...\n\n' + contactBlock;
  }

  return full.slice(0, Math.max(0, maxLength - 3)).trim() + '...';
}

const header = '\ud83d\udce3 ' + platform + ' COPY\n\ud83c\udfe2 ' + company + '\n\ud83e\uddfe ' + contentId + '\n\n';
const footer = '\n\n\ud83d\udd0e REVIEW COPY \u2014 Telegram does not publish this content';
const maxBody = Math.max(0, 3900 - header.length - footer.length);

return { json: {
  telegram_copy_needed: true,
  telegram_chat_id: preview.telegram_chat_id,
  telegram_message: header + fitBody(preview.telegram_copy, maxBody) + footer,
  telegram_platform: platform,
  content_id: contentId,
  reply_to_message_id: messageId,
} };

