// v9.5.0: Pexels stock footage was removed - it could not supply clips of a technician
// performing the requested service (verified across HVAC, electrical and plumbing).
// Google Gemini generates the scene directly from video_brief / video_script instead.
const source = $json;
const cfg = $('Runtime Configuration').first().json;
const target = String(source.target_platform || '').trim().toLowerCase();
const requested = Number(source.video_duration_seconds || cfg.video_duration_seconds || 8);
const duration = Math.max(3, Math.min(10, Number.isFinite(requested) && requested >= 3 ? requested : 8));
const aspectRatio = ['9:16','16:9'].includes(String(source.video_aspect_ratio || ''))
  ? String(source.video_aspect_ratio)
  : (target === 'instagram' ? '9:16' : '16:9');
return {
  json: {
    ...source,
    id: source.id,
    video_status: 'Generating',
    video_attempts: Number(source.video_attempts || 0) + 1,
    video_provider: 'Google Gemini',
    video_duration_seconds: duration,
    video_aspect_ratio: aspectRatio,
    last_error: '',
    next_retry_at: '',
    updated_at: new Date().toISOString()
  }
};

// v9.5.2 FIX: never read the row from $json here. On this path $json comes from
// 'Lock Video Row', a Google Sheets node whose response only echoes the columns it WROTE
// (id, video_status, attempts, provider, duration, aspect, timestamps) - it has no
// content_pillar / topic_idea / video_brief / video_script, which produced an empty prompt.
// 'Prepare Video Lock' holds the complete row, so read it directly (.first() is used
// because pairedItem is not reliable across the Sheets node).
const source = $('Prepare Video Lock').first().json;
const cfg = $('Runtime Configuration').first().json;
const clean = value => String(value ?? '').trim();
const intent = [source.campaign, source.content_pillar, source.topic_idea].map(clean).join(' ').toLowerCase();
const isOccasion = /social occasion|holiday|eid|ramadan|christmas|easter|new year|thanksgiving|labor day|independence day|good friday|palm sunday|mawlid|women.?s day|mother.?s day|army day|teacher.?s day|مناسبة|عيد|رمضان|الاستقلال|المولد|رأس السنة|الإسراء|يوم الجيش|يوم العمال|تهنئة|جمعة مباركة/.test(intent);
const isRecruitment = /recruitment|hiring|career|job vacancy|job posting|توظيف|وظيفة|شاغر/.test(intent);
const duration = Math.max(3, Math.min(10, Number(source.video_duration_seconds || cfg.video_duration_seconds || 8)));
const subjectRule = isOccasion
  ? 'Represent only the exact named occasion as celebrated in Jordan with an elegant, respectful, culturally appropriate real-world scene. Do not insert installation work or sales promotion.'
  : isRecruitment
    ? 'Show an authentic professional performing work relevant to the supplied job role in a credible environment. Do not invent qualifications or show vacancy text.'
    : 'Show the exact supplied Peak PV service in a real Jordanian setting (flat concrete rooftop with water tanks, farm, poultry house, well pump, small workshop, or a villa with a home EV charger). When people work, show qualified installers with helmets, harnesses and gloves actively mounting panels, fixing rails, or connecting an inverter safely. Never show a commercial shop as the customer.';
const prompt = [
  `Create a ${duration}-second professional social-media marketing video for ${clean(source.company_name) || 'a Jordanian solar company'}.`,
  `Aspect ratio: ${source.video_aspect_ratio}. Resolution target: ${cfg.video_resolution || '1080p'}.`,
  `Required subject: ${clean(source.content_pillar)}.`,
  `Required scenario and source details: ${clean(source.topic_idea)}.`,
  `Creative direction: ${clean(source.video_brief)}.`,
  `Timecoded action plan: ${clean(source.video_script)}.`,
  subjectRule,
  'In a single continuous unbroken shot. No scene cuts. Use restrained, physically plausible camera movement and realistic subject motion.',
  'Editorial commercial cinematography, natural skin tones, accurate anatomy and tools, believable materials, controlled highlights, crisp focal detail, subtle depth, realistic physics, and clean color separation. Avoid a plastic, oversaturated, or obviously AI-generated look.',
  'Sound design: realistic location ambience and subtle tool or environmental sounds only. No dialogue, no voiceover, no copyrighted music, no jingle.',
  'Absolutely no on-screen text, letters, numbers, captions, subtitles, labels, signs, logos, brand marks, prices, maps, customer data, or watermarks.',
  'No unsafe work, sparks, flames, exposed live conductors, dramatic hazards, extra limbs, warped hands, duplicated people, morphing tools, unstable equipment, unrelated trades, collages, before-and-after split screens, or scene changes.',
  'Keep the primary subject inside safe social-media crop margins for the requested aspect ratio.'
].join('\n');
return {
  json: { ...source, video_generation_prompt: prompt },
  binary: $binary
};

