parameters.jsCode:
const source = $('Parse Video File Status').item.json;
const response = $json;

// v9.5.5: the AI quality check is now BEST-EFFORT. A rate limit (429), an outage, or a
// malformed reply used to throw the whole row away - discarding a video that had already
// generated successfully and been paid for. The human approval gate and the two-stage
// audit are the real quality gates, so on any QA failure the video passes through with
// the reason recorded instead of being destroyed.
function qaSkipped(reason) {
  return { json: {
    ...source,
    video_qa_passed: true,
    video_qa_confidence: 0,
    video_qa_reason: 'Automated QA skipped (' + String(reason).slice(0, 200) + '). Human review required.'
  } };
}

const httpError = response?.error?.message || response?.body?.error?.message || response?.error;
if (httpError) return qaSkipped(typeof httpError === 'string' ? httpError : JSON.stringify(httpError));

try {
  const contents = (response.steps || []).flatMap(step => Array.isArray(step.content) ? step.content : []);
  let raw = contents.filter(item => item?.type === 'text' && item.text).map(item => item.text).pop() || response.output_text || '';
  raw = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const objectMatch = raw.match(/\{[\s\S]*\}/);
  if (objectMatch) raw = objectMatch[0];
  if (!raw) return qaSkipped('QA returned no JSON result');
  const result = JSON.parse(raw);
  const threshold = Number($('Runtime Configuration').first().json.video_qa_threshold || 0.80);
  const passed = result.matches_topic === true
    && result.matches_active_task === true
    && result.coherent_motion === true
    && result.safe_and_realistic === true
    && result.professional_visual_quality === true
    && result.has_forbidden_text_or_logo === false
    && Number(result.confidence || 0) >= threshold;
  return { json: {
    ...source,
    video_qa_passed: passed,
    video_qa_confidence: Number(result.confidence || 0),
    video_qa_reason: String(result.reason || '').trim()
  } };
} catch (e) {
  return qaSkipped(e.message);
}

const source = $('Parse Video Validation').item.json;
const binaries = $binary || {};
const binaryKey = binaries.data ? 'data' : Object.keys(binaries)[0];
const incoming = binaryKey ? binaries[binaryKey] : null;
if (!incoming) throw new Error('The final Gemini video download did not return binary data.');
const safeId = String(source.id || 'video').replace(/[^a-zA-Z0-9_-]/g, '-');
const data = {
  ...incoming,
  fileName: safeId + '.mp4',
  fileExtension: 'mp4',
  mimeType: 'video/mp4'
};
return { json: { ...source, video_file_name: data.fileName }, binary: { data } };

const source = $('Prepare Branded Video Binary').item.json;
const fileId = String($('Upload Branded Video to Google Drive').item.json.id || '').trim();
if (!fileId) throw new Error('Branded Google Drive video upload did not return a file ID.');
return { json: {
  id: source.id,
  video_status: 'Ready',
  video_file_id: fileId,
  video_url: 'https://drive.usercontent.google.com/download?id=' + fileId + '&export=download',
  video_attempts: Number(source.video_attempts || 1),
  video_provider: source.video_provider || 'Google Gemini',
  video_duration_seconds: Number(source.video_duration_seconds || 8),
  video_aspect_ratio: source.video_aspect_ratio || '16:9',
  status: 'Awaiting Approval',
  last_error: '',
  next_retry_at: '',
  updated_at: new Date().toISOString()
} };

let source = {};
for (const name of ['Parse Branded Video Status','Parse Creatomate Video Render','Parse Video Validation','Parse Video File Status','Parse Video Generation','Build Video Generation Request','Prepare Video Lock']) {
  try { const candidate = $(name).first().json || {}; if (candidate.id) { source = candidate; break; } } catch {}
}
const raw = $json.error?.message || $json.body?.error?.message || $json.error_message || $json.message || $json.error || source._creatomate_video_error || source._video_file_error || 'Unknown video generation, branding, validation, download, or upload error';
const message = typeof raw === 'string' ? raw : JSON.stringify(raw);
const retryMinutes = Number($('Runtime Configuration').first().json.retry_minutes || 10);
return { json: { id: source.id, video_status: 'Failed', video_attempts: Number(source.video_attempts || 1), video_provider: source.video_provider || $('Runtime Configuration').first().json.video_provider || 'Google Gemini', video_duration_seconds: Number(source.video_duration_seconds || 8), video_aspect_ratio: source.video_aspect_ratio || '16:9', status: 'Awaiting Approval', last_error: ('Video workflow failed: ' + message).slice(0, 1000), next_retry_at: new Date(Date.now() + retryMinutes * 60000).toISOString(), updated_at: new Date().toISOString() } };

const source = $('Prepare Video Lock').item.json;
return { json: {
  id: source.id,
  video_status: 'Failed',
  video_attempts: Number(source.video_attempts || 1),
  video_provider: source.video_provider || 'Google Gemini',
  video_duration_seconds: Number(source.video_duration_seconds || 8),
  video_aspect_ratio: source.video_aspect_ratio || '16:9',
  status: 'Awaiting Approval',
  last_error: ('Video quality check rejected the result: ' + String($json.video_qa_reason || 'The video did not clearly match the requested service or quality bar.')).slice(0, 1000),
  next_retry_at: new Date(Date.now() + 2 * 60000).toISOString(),
  updated_at: new Date().toISOString()
} };

// v9.5.6 FIX: `return []` is invalid in per-item mode ("A 'json' property isn't an object").
// Switched to all-items mode so that, when Telegram previews are disabled or no chat id is
// configured, the node emits nothing instead of throwing. Binary data is carried per item.
const cfg = $('Runtime Configuration').first().json;
const enabled = cfg.telegram_preview_enabled === true || String(cfg.telegram_preview_enabled).toLowerCase() === 'true';
const chatId = String(cfg.telegram_chat_id || '').trim();
if (!enabled || !chatId || chatId === 'YOUR_TELEGRAM_CHAT_ID') return [];

const out = [];
for (const item of $input.all()) {
  const source = item.json || {};
  const target = String(source.target_platform || '').trim().toLowerCase();
  const copy = target === 'facebook' ? source.generated_facebook : target === 'instagram' ? source.generated_instagram : source.generated_linkedin;
  const caption = [
    '\ud83c\udfac ' + (target ? target.toUpperCase() : 'VIDEO') + ' \u2014 ' + String(source.company_name || source.brand_id || 'Peak PV'),
    '\ud83e\uddfe ' + String(source.id || ''),
    '\ud83c\udfa8 Branding: Creatomate \u2014 ' + String(source.video_provider || 'Video'),
    ...(Number(source.video_qa_confidence || 0) > 0
      ? ['\u2705 Gemini Video QA: ' + Math.round(Number(source.video_qa_confidence || 0) * 100) + '%']
      : ['\u2705 Branded source image + successful video render']),
    '',
    String(copy || '').trim()
  ].join('\n').slice(0, 1024);
  out.push({ json: { ...source, telegram_chat_id: chatId, telegram_caption: caption }, binary: item.binary });
}
return out;

return { json: {
  statusCode: 422,
  body: {
    message: 'The high-quality video was generated and saved, but LinkedIn video publishing requires the LinkedIn Videos API multipart asset-upload flow. This workflow intentionally did not publish a text-only replacement. Publish the Drive video manually or add an approved LinkedIn video-upload credential/adapter.'
  }
} };

