const locked = $('Prepare Video Lock').item.json;
let source = locked;
try {
  const qa = $('Parse Video Validation').item.json || {};
  if (qa.id === locked.id) source = { ...source, ...qa };
} catch {}
const response = $json.body ?? $json;
const render = Array.isArray(response) ? response[0] : response;
if (!render?.id) throw new Error('Creatomate video render did not return a render ID.');
return { json: {
  ...source,
  _creatomate_video_render_id: String(render.id),
  _creatomate_video_status: String(render.status || 'planned').toLowerCase(),
  _creatomate_video_url: String(render.url || ''),
  _creatomate_video_error: String(render.error_message || ''),
  _creatomate_video_poll_count: 0
} };

let source = {};
try { source = $('Increment Branded Video Poll').item.json || {}; } catch {}
if (!source._creatomate_video_render_id) source = $('Parse Creatomate Video Render').item.json;
const response = $json.body ?? $json;
const render = Array.isArray(response) ? response[0] : response;
return { json: { ...source, _creatomate_video_status: String(render?.status || 'planned').toLowerCase(), _creatomate_video_url: String(render?.url || source._creatomate_video_url || ''), _creatomate_video_error: String(render?.error_message || '') } };

const source = $('Parse Branded Video Status').item.json;
const binaries = $binary || {};
const binaryKey = binaries.data ? 'data' : Object.keys(binaries)[0];
const incoming = binaryKey ? binaries[binaryKey] : null;

if (!incoming) {
  throw new Error('Creatomate branded video download did not return binary data.');
}

const safeId = String(source.id || 'video')
  .replace(/[^a-zA-Z0-9_-]/g, '-');

const data = {
  ...incoming,
  fileName: safeId + '-branded.mp4',
  fileExtension: 'mp4',
  mimeType: 'video/mp4'
};

return {
  json: {
    ...source,
    branding_status: 'Branded',
    branded_by: 'Creatomate',
    video_file_name: data.fileName
  },
  binary: { data }
};

const src = $('Build Platform Jobs').item.json;
const res = $json || {};
const msgId = res.result?.message_id ?? res.message_id ?? '';
const ok = !res.error && (res.ok === true || msgId !== '');
const error = ok ? '' : String(res.error?.message || res.error || res.description || 'Telegram publishing failed.');
const now = new Date();
return { json: {
  id: src.id,
  telegram_status: ok ? 'Published' : 'Failed',
  telegram_post_id: ok ? String(msgId) : '',
  telegram_attempts: src._attempt,
  updated_at: now.toISOString(),
  log_id: src.id + '-telegram-' + Date.now(),
  post_id: src.id,
  brand_id: src.brand_id,
  company_name: src.company_name,
  platform: 'telegram',
  platform_status: ok ? 'Published' : 'Failed',
  platform_post_id: ok ? String(msgId) : '',
  attempt: src._attempt,
  error_message: error,
  platform_published_at: ok ? now.toISOString() : '',
  logged_at: now.toISOString()
} };

// Peak PV: posts are images + Arabic text only on every platform. Video production is switched off.
// Any row still waiting for a draft or media is converted to media_type = Image before classification.
const OPEN = ['needs draft', 'draft requested', 'awaiting approval'];
return $input.all().map(item => {
  const row = { ...item.json };
  const state = String(row.status || '').trim().toLowerCase();
  const media = String(row.media_type || '').trim();
  if (OPEN.includes(state) && media !== 'Image') {
    row.media_type = 'Image';
    row.video_status = 'Not Requested';
    if (!String(row.image_url || '').trim() && ['', 'not requested'].includes(String(row.image_status || '').trim().toLowerCase())) row.image_status = 'Pending';
  }
  return { json: row, pairedItem: item.pairedItem };
});
